const ALL_TOOLS = CATEGORIES.flatMap(cat =>
  cat.tools.map(t => ({ ...t, catId: cat.id, catTitle: cat.title, catColor: cat.color, catIcon: cat.icon }))
);

function getDomain(url) {
  try { return new URL(url).hostname.replace('www.', ''); } catch { return ''; }
}

function badgeLabel(b) {
  const map = { free: t('badge.free'), freemium: 'Freemium', paid: t('badge.paid') };
  return map[b] || b;
}

function localizePrice(price) {
  if (!price) return price;
  const lang = (typeof I18N !== 'undefined' ? I18N.lang : null) || localStorage.getItem('lang') || 'en';
  const FROM = { ru:'от', es:'desde', de:'ab', ua:'від', he:'מ-', fr:'dès', pt:'a partir de' };
  const MO   = { ru:'/мес', es:'/mes', de:'/Mo.', ua:'/міс', he:"/חו'", fr:'/mois', pt:'/mês' };
  const FREE = { ru:'Бесплатно', es:'Gratis', de:'Kostenlos', ua:'Безкоштовно', he:'חינם', fr:'Gratuit', pt:'Grátis' };
  const from = FROM[lang] || 'from';
  const mo   = MO[lang]   || '/mo';
  const free = FREE[lang]  || 'Free';
  if (price === 'Free') return free;
  const m = price.match(/from \$(\d+(?:\.\d+)?)/);
  if (!m) return price;
  const amt = m[1];
  return price.startsWith('Free /') ? `${free} / ${from} $${amt}${mo}` : `${from} $${amt}${mo}`;
}

function toSlug(name) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function renderToolCard(tool, color) {
  const c = color || tool.catColor || '#7c6af7';
  const domain = getDomain(tool.url);
  const faviconSrc = `https://www.google.com/s2/favicons?sz=64&domain=${domain}`;
  const isPrice = tool.users && (tool.users.startsWith('Free') || tool.users.startsWith('from $'));
  const badgeLbl = (tool.badge === 'paid' && isPrice) ? localizePrice(tool.users) : badgeLabel(tool.badge);
  const usersHtml = (tool.users && !isPrice) ? `<span class="tool-users">👥 ${tool.users}</span>` : '';
  const slug = tool.slug || toSlug(tool.name);
  const _lang = (typeof I18N !== 'undefined' ? I18N.lang : null) || localStorage.getItem('lang') || 'en';
  const reviewUrl = _lang === 'en' ? `/tools/${slug}.html` : `/${_lang}/tools/${slug}.html`;
  return `
    <div class="tool-card fade-up" onclick="window.location.href='${reviewUrl}'" style="cursor:pointer">
      <div class="tool-card-top">
        <div class="tool-avatar" style="background:${c}22;border-color:${c}44;">
          <img class="tool-favicon" src="${faviconSrc}" alt="" width="24" height="24"
            onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
          <span class="tool-avatar-fallback" style="display:none;color:${c}">${tool.name[0]}</span>
        </div>
        <span class="tool-name">${tool.name}</span>
        ${usersHtml}
        <span class="badge badge-${tool.badge}">${badgeLbl}</span>
      </div>
      <p class="tool-desc">${getToolDesc(tool)}</p>
      <div class="tool-footer">
        <span class="tool-domain">${domain}</span>
        <div style="display:flex;align-items:center;gap:6px">
          <a class="tool-review" href="${reviewUrl}" onclick="event.stopPropagation()">${t('tool.review')}</a>
          <a class="tool-aff" href="${tool.aff || tool.url}" target="_blank" rel="noopener sponsored" onclick="event.stopPropagation()">${t('tool.open')}</a>
        </div>
      </div>
    </div>`;
}
